const input=document.getElementById("text-input");function updateStats(){const t=input.value,e=t.replace(/\s/g,""),n=t.trim()?t.trim().split(/\s+/).length:0,o=t?t.split(`
`).length:0,s=new Blob([t]).size,c=t.trim()?t.split(/[.!?。！？]+/).filter(i=>i.trim()).length:0;document.getElementById("stat-chars").textContent=t.length.toLocaleString(),document.getElementById("stat-chars-no-space").textContent=e.length.toLocaleString(),document.getElementById("stat-words").textContent=n.toLocaleString(),document.getElementById("stat-lines").textContent=o.toLocaleString(),document.getElementById("stat-bytes").textContent=s.toLocaleString(),document.getElementById("stat-sentences").textContent=c.toLocaleString()}input.addEventListener("input",updateStats);function copyText(){copyToClipboard(input.value).then(()=>showToast(i18n.t("common.copied")))}function downloadResult(){const t=input.value,e=[i18n.t("common.stats_title"),"",`${i18n.t("common.stats_chars")}: ${t.length.toLocaleString()}`,`${i18n.t("common.stats_chars_no_space")}: ${t.replace(/\s/g,"").length.toLocaleString()}`,`${i18n.t("common.stats_words")}: ${t.trim()?t.trim().split(/\s+/).length:0}`,`${i18n.t("common.stats_lines")}: ${t?t.split(`
`).length:0}`,`${i18n.t("common.stats_bytes")}: ${new Blob([t]).size.toLocaleString()}`,`${i18n.t("common.stats_sentences")}: ${t.trim()?t.split(/[.!?。！？]+/).filter(n=>n.trim()).length:0}`,"",i18n.t("common.stats_input_text"),t].join(`
`);downloadFile(e,"text-stats.txt")}function clearText(){input.value="",updateStats()}
